mapper.select:
SELECT y.* FROM (SELECT a.yearMonth, a.extUseType, a.year, a.month, b.thisYearQuantity, a.thisMonthQuantity, b_last_month.thisMonthQuantity AS lastMonthQuantity FROM (SELECT 'INVITE' extUseType, DATE_FORMAT(info.APPROVED_DATE, '%Y-%m') yearMonth, YEAR(info.APPROVED_DATE) year, MONTH(info.APPROVED_DATE) month, count(1) thisMonthQuantity FROM meicloud_usrm_cloud_biz_supplier.scc_sup_company_info info WHERE info.EXT_USE_TYPE IN ('COMMON', '', 'INVITE') AND info.STATUS = 'APPROVED' AND info.IS_BACKLIST = 'N' AND info.APPROVED_DATE IS NOT NULL GROUP BY DATE_FORMAT(info.APPROVED_DATE, '%Y-%m')) a LEFT JOIN (SELECT YEAR(b.APPROVED_DATE) year, count(1) thisYearQuantity FROM meicloud_usrm_cloud_biz_supplier.scc_sup_company_info b WHERE b.EXT_USE_TYPE IN ('COMMON', '', 'INVITE') AND b.STATUS = 'APPROVED' AND b.IS_BACKLIST = 'N' AND b.APPROVED_DATE IS NOT NULL GROUP BY YEAR(b.APPROVED_DATE)) b on a.year = b.year LEFT JOIN (SELECT DATE_FORMAT(DATE_ADD(b.APPROVED_DATE, INTERVAL 1 MONTH), '%Y-%m') yearMonth, COUNT(1) AS thisMonthQuantity FROM meicloud_usrm_cloud_biz_supplier.scc_sup_company_info b WHERE b.EXT_USE_TYPE IN ('COMMON', '', 'INVITE') AND b.STATUS = 'APPROVED' AND b.IS_BACKLIST = 'N' AND b.APPROVED_DATE IS NOT NULL GROUP BY DATE_FORMAT(APPROVED_DATE, '%Y-%m')) b_last_month ON a.yearMonth = b_last_month.yearMonth UNION ALL SELECT a.yearMonth, a.extUseType, a.year, a.month, b.thisYearQuantity, a.thisMonthQuantity, b_last_month.thisMonthQuantity AS lastMonthQuantity FROM (SELECT 'TEMP_PROCUREMENT' extUseType, DATE_FORMAT(info.APPROVED_DATE, '%Y-%m') yearMonth, YEAR(info.APPROVED_DATE) year, MONTH(info.APPROVED_DATE) month, count(1) thisMonthQuantity FROM meicloud_usrm_cloud_biz_supplier.scc_sup_company_info info WHERE info.EXT_USE_TYPE IN ('COMMON', '', 'TEMP_PROCUREMENT') AND info.STATUS = 'APPROVED' AND info.IS_BACKLIST = 'N' AND info.APPROVED_DATE IS NOT NULL GROUP BY DATE_FORMAT(info.APPROVED_DATE, '%Y-%m')) a LEFT JOIN (SELECT YEAR(b.APPROVED_DATE) year, count(1) thisYearQuantity FROM meicloud_usrm_cloud_biz_supplier.scc_sup_company_info b WHERE b.EXT_USE_TYPE IN ('COMMON', '', 'TEMP_PROCUREMENT') AND b.STATUS = 'APPROVED' AND b.IS_BACKLIST = 'N' AND b.APPROVED_DATE IS NOT NULL GROUP BY YEAR(b.APPROVED_DATE)) b on a.year = b.year LEFT JOIN (SELECT DATE_FORMAT(DATE_ADD(b.APPROVED_DATE, INTERVAL 1 MONTH), '%Y-%m') yearMonth, COUNT(1) AS thisMonthQuantity FROM meicloud_usrm_cloud_biz_supplier.scc_sup_company_info b WHERE b.EXT_USE_TYPE IN ('COMMON', '', 'TEMP_PROCUREMENT') AND b.STATUS = 'APPROVED' AND b.IS_BACKLIST = 'N' AND b.APPROVED_DATE IS NOT NULL GROUP BY DATE_FORMAT(APPROVED_DATE, '%Y-%m')) b_last_month ON a.yearMonth = b_last_month.yearMonth) y
AND y.extUseType=#{extUseType}
AND y.year=#{year}
AND y.month=#{month}
ORDER BY y.yearMonth DESC, y.extUseType

SELECT a.SOU_TYPE, DATE_FORMAT(a.PUBLISH_TIME, '%Y-%m') yearMonth, YEAR(a.PUBLISH_TIME) year, MONTH(a.PUBLISH_TIME) month, count(1) quantity FROM meicloud_usrm_cloud_biz_sou.scc_sou_project a INNER JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_bid_notice b ON a.PROJECT_ID = b.project_id WHERE a.SOU_TYPE IN ('bid', 'ext_pur_inq') AND b.status = 'APPROVED' AND a.PUBLISH_TIME IS NOT NULL
AND a.SOU_TYPE=#{souType}
AND YEAR(a.PUBLISH_TIME)=#{year}
AND MONTH(a.PUBLISH_TIME)=#{month}
GROUP BY yearMonth DESC, a.SOU_TYPE

SELECT y.* FROM (SELECT a.yearMonth, a.year, a.month, a.thisMonthQuantity, b_last_month.thisMonthQuantity AS lastMonthQuantity FROM (SELECT DATE_FORMAT(a.EFFECTIVE_TIME, '%Y-%m') yearMonth, YEAR(a.EFFECTIVE_TIME) year, MONTH(a.EFFECTIVE_TIME) month, COUNT(1) AS thisMonthQuantity FROM meicloud_usrm_cloud_biz_supplier.scc_base_black a INNER JOIN meicloud_usrm_cloud_biz_supplier.scc_base_black_company b ON a.BLACK_ID = b.BLACK_ID WHERE a.EFFECTIVE_TIME is not null GROUP BY yearMonth) a LEFT JOIN (SELECT DATE_FORMAT(DATE_ADD(a.EFFECTIVE_TIME, INTERVAL 1 MONTH), '%Y-%m') yearMonth, COUNT(1) AS thisMonthQuantity FROM meicloud_usrm_cloud_biz_supplier.scc_base_black a INNER JOIN meicloud_usrm_cloud_biz_supplier.scc_base_black_company b ON a.BLACK_ID = b.BLACK_ID WHERE a.EFFECTIVE_TIME is not null GROUP BY yearMonth) b_last_month ON a.yearMonth = b_last_month.yearMonth) y
AND YEAR(a.EFFECTIVE_TIME)=#{year}
AND MONTH(a.EFFECTIVE_TIME) =#{month}
ORDER BY y.yearMonth DESC

SELECT DATE_FORMAT(f.START_DATE, '%Y-%m') yearMonth, f.SUPPLIER_CONTROL_TYPE, COUNT(1) quantity FROM meicloud_usrm_cloud_biz_supplier.scc_sup_auth_org_cat_form f WHERE NOT EXISTS(SELECT 1 FROM meicloud_usrm_cloud_biz_supplier.scc_base_black b INNER JOIN meicloud_usrm_cloud_biz_supplier.scc_base_black_company c ON b.BLACK_ID = c.BLACK_ID WHERE b.APPROVE_STATUS = 'APPROVED' AND f.VENDOR_ID = c.COMPANY_ID AND f.START_DATE BETWEEN b.EFFECTIVE_TIME AND b.END_DATE) AND f.SUPPLIER_CONTROL_TYPE IN ('TIME_LIMIT_FLAG', 'CATEGORY_LIMIT_FLAG', 'POSITION_LIMIT_FLAG') AND f.START_DATE IS NOT NULL
AND DATE_FORMAT(f.START_DATE, '%Y-%m')=#{yearMonth}
AND f.SUPPLIER_CONTROL_TYPE=#{supplierControlType}
GROUP BY yearMonth, f.SUPPLIER_CONTROL_TYPE ORDER BY yearMonth DESC

SELECT a.EXT_ORG_BU_NAME, a.EXT_ORG_OU_NAME, a.EXT_PROJECT_NO, a.EXT_BUDGET, notice.win_amount, notice.pass_time, YEAR(notice.pass_time) year FROM meicloud_usrm_cloud_biz_sou.scc_sou_project a LEFT JOIN (SELECT b.project_id,MAX(b.pass_time) pass_time, SUM(IFNULL(c.win_amount, 0)) win_amount FROM meicloud_usrm_cloud_biz_sou.scc_npm_sou_bid_notice b INNER JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_bid_notice_detail c ON b.bid_notice_id = c.bid_notice_id WHERE c.is_win = 'Y' AND c.win_amount != 1 AND b.status = 'APPROVED' GROUP BY b.project_id) notice ON a.PROJECT_ID = notice.project_id where a.PROJECT_STATUS='ARCHIVE_DONE'
AND a.EXT_ORG_BU_NAME=#{extOrgBuName}
AND a.EXT_ORG_OU_NAME=#{extOrgOuName}
AND a.EXT_BUDGET>=#{extBudget}
AND notice.win_amount>=#{winAmount}
ORDER BY notice.pass_time DESC

SELECT y.EXT_ORG_BU_NAME, y.EXT_ORG_OU_NAME, YEAR(MAX(y.APPROVAL_PASS_TIME)) year, count(1) quantity FROM (select distinct a.PROJECT_ID, a.EXT_ORG_BU_NAME, a.EXT_ORG_OU_NAME, e.APPROVAL_PASS_TIME from meicloud_usrm_cloud_biz_sou.scc_sou_project a INNER JOIN meicloud_usrm_cloud_biz_sou.scc_npm_sou_bid_notice b ON a.PROJECT_ID = b.project_id inner join meicloud_usrm_cloud_biz_sou.scc_npm_sou_demand c on a.PROJECT_ID = c.PROJECT_ID inner join meicloud_usrm_cloud_biz_supplier_cooperate.scc_pr_requirement_head d on c.APPLICANT_NO = d.REQUIREMENT_HEAD_NUM and d.AUDIT_STATUS != 'ABANDONED' inner join meicloud_usrm_cloud_biz_supplier_cooperate.scc_npm_pr_require_head e on d.REQUIREMENT_HEAD_ID = e.REQUIREMENT_HEAD_ID WHERE a.EXT_ORG_BU_NAME != '' AND a.EXT_ORG_OU_NAME != '' AND e.APPROVAL_PASS_TIME IS NOT NULL AND e.REQUIRE_FROM = 'SPECIAL_SOU'
AND a.EXT_ORG_BU_NAME =#{extOrgBuName}
AND a.EXT_ORG_OU_NAME=#{extOrgOuName}
AND YEAR( e.APPROVAL_PASS_TIME)=#{year}
) y GROUP BY y.EXT_ORG_BU_NAME, y.EXT_ORG_OU_NAME ORDER BY quantity DESC

SELECT YEAR(LAST_UPDATE_DATE)                              YEAR,
       PERFORMANCE_TYPE,
       LEVEL_NAME,
       COUNT(*) AS                                         QUANTITY
FROM meicloud_usrm_cloud_biz_performance.scc_npm_project_score_header
WHERE PERFORMANCE_TYPE IN ('NODE', 'PROJECT')

    AND YEAR(LAST_UPDATE_DATE)=#{year}


    AND PERFORMANCE_TYPE=#{performanceType}


    AND LEVEL_NAME=#{levelName}

GROUP BY YEAR, PERFORMANCE_TYPE, LEVEL_NAME
